<?php
namespace ProjectPress\Admin\Manager\ProjectManager;
use ProjectPress\Includes\Functions\Helpers\RequestHelper;
use ProjectPress\Includes\Project\Core\TeamRepository;
if ( ! defined( 'ABSPATH' ) ) { exit; }
final class Teams { private TeamRepository $repository; public function __construct() { $this->repository = new TeamRepository(); }
	public function render(): void { $teams = $this->repository->all(); ?><div class="row g-4"><div class="col-lg-5"><div class="card card-body"><h2 class="h4"><?php esc_html_e( 'Create Team', 'projectpress' ); ?></h2><form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><input type="hidden" name="action" value="projectpress_team_save"/><?php wp_nonce_field( 'projectpress_team_save' ); ?><label class="form-label" for="team-name"><?php esc_html_e( 'Name', 'projectpress' ); ?></label><input class="form-control" id="team-name" name="name" required/><label class="form-label mt-3" for="team-description"><?php esc_html_e( 'Description', 'projectpress' ); ?></label><textarea class="form-control" id="team-description" name="description"></textarea><button class="btn btn-primary mt-3" type="submit"><?php esc_html_e( 'Create Team', 'projectpress' ); ?></button></form></div></div><div class="col-lg-7"><div class="card card-body"><h2 class="h4"><?php esc_html_e( 'Teams', 'projectpress' ); ?></h2><?php foreach ( $teams as $team ) : ?><div class="border-bottom py-2"><strong><?php echo esc_html( $team['team_name'] ); ?></strong><div class="text-secondary"><?php echo esc_html( $team['team_description'] ); ?></div></div><?php endforeach; if ( empty( $teams ) ) : ?><p><?php esc_html_e( 'No teams found.', 'projectpress' ); ?></p><?php endif; ?></div></div></div><?php }
	public function handle_save(): void { check_admin_referer( 'projectpress_team_save' ); if ( ! current_user_can( 'manage_options' ) && ! current_user_can( 'projectpress_teams_manage' ) ) { wp_die( esc_html__( 'You are not authorised to manage teams.', 'projectpress' ) ); } $this->repository->create( array( 'name' => RequestHelper::text( $_POST, 'name', '' ), 'description' => RequestHelper::text( $_POST, 'description', '' ) ) ); wp_safe_redirect( admin_url( 'admin.php?page=projectpress&group=project-manager&tab=teams' ) ); exit; }
}
